(()=>{'use strict';const menuToggle=document.querySelector('.menu-toggle');const primaryNav=document.querySelector('.primary-nav');const dropdown=document.querySelector('.nav-dropdown');const dropdownTrigger=document.querySelector('.dropdown-trigger');const yearElement=document.querySelector('#current-year');if(yearElement)yearElement.textContent=String(new Date().getFullYear());const currentFile=(window.location.pathname.split('/').pop()||'index.html').toLowerCase();const activeNav=currentFile==='index.html'||currentFile===''?'home':currentFile==='kurumsal.html'?'kurumsal':currentFile==='markalar.html'?'brands':currentFile==='teklif-al.html'?'quote':currentFile==='iletisim.html'?'contact':currentFile==='kurumsal-toplu-tedarik.html'?'supply':/^rehber(-[a-z0-9-]+)?\.html$/.test(currentFile)?'guide':(currentFile==='urun-gruplari.html'||/^(toner-kartus|kartus-murekkep|yazici-fotokopi|kagit-etiket|bilgisayar-cevre-birimleri|bilgisayar-bilesenleri|tablet-mobil-cihazlar|ergonomik-calisma-urunleri|ag-iletisim-urunleri|kablo-baglanti-urunleri|telefon-santral-urunleri|ups-guc-cozumleri|yazilim-lisans|depolama-bellek|sunucu-veri-merkezi|tarayici-arsiv-urunleri|ofis-makineleri|sunum-toplanti-urunleri|dijital-tabela-ekran|guvenlik-sistemleri|gecis-kontrol-alarm|barkod-pos-urunleri|yazarkasa-perakende-urunleri)\.html$/.test(currentFile))?'products':'';document.querySelectorAll('[data-nav]').forEach((link)=>{const isCurrent=link.dataset.nav===activeNav;link.classList.toggle('active',isCurrent);if(isCurrent)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});function closeProductMenu(restoreFocus=false){
  const wasOpen=Boolean(dropdown?.classList.contains('open'));
  dropdown?.classList.remove('open');
  dropdownTrigger?.setAttribute('aria-expanded','false');
  if(restoreFocus&&wasOpen)dropdownTrigger?.focus();
}
function closeMobileMenu(restoreFocus=false){
  const wasOpen=Boolean(primaryNav?.classList.contains('open'));
  if(!menuToggle||!primaryNav)return;
  menuToggle.setAttribute('aria-expanded','false');
  menuToggle.setAttribute('aria-label','Menüyü aç');
  primaryNav.classList.remove('open');
  closeProductMenu();
  if(restoreFocus&&wasOpen)menuToggle.focus();
}
menuToggle?.addEventListener('click',()=>{
  const isOpen=menuToggle.getAttribute('aria-expanded')==='true';
  if(isOpen){closeMobileMenu();return;}
  menuToggle.setAttribute('aria-expanded','true');
  menuToggle.setAttribute('aria-label','Menüyü kapat');
  primaryNav?.classList.add('open');
});
dropdownTrigger?.addEventListener('click',(event)=>{
  event.stopPropagation();
  const isOpen=dropdownTrigger.getAttribute('aria-expanded')==='true';
  if(isOpen){closeProductMenu();return;}
  dropdownTrigger.setAttribute('aria-expanded','true');
  dropdown?.classList.add('open');
});
document.addEventListener('click',(event)=>{
  if(dropdown&&!dropdown.contains(event.target))closeProductMenu();
  if(primaryNav?.classList.contains('open')&&!primaryNav.contains(event.target)&&!menuToggle?.contains(event.target))closeMobileMenu();
});
document.addEventListener('keydown',(event)=>{
  if(event.key!=='Escape')return;
  if(dropdown?.classList.contains('open')){
    event.preventDefault();
    closeProductMenu(true);
    return;
  }
  if(primaryNav?.classList.contains('open')){
    event.preventDefault();
    closeMobileMenu(true);
  }
});
primaryNav?.querySelectorAll('a').forEach((link)=>link.addEventListener('click',()=>closeMobileMenu()));
})();
/* VK V02: Keep the floating WhatsApp shortcut clear of visible forms on small screens. */
(() => {
  const floatingContact = document.querySelector('.floating-contact');
  const contactForm = document.querySelector('#home-contact-form, #contact-form');
  if (!floatingContact || !contactForm || !window.matchMedia || !('IntersectionObserver' in window)) return;

  const mobileViewport = window.matchMedia('(max-width: 768px)');
  let formVisible = false;
  const syncVisibility = () => {
    floatingContact.classList.toggle('is-hidden-over-form', mobileViewport.matches && formVisible);
  };
  const observer = new IntersectionObserver((entries) => {
    formVisible = entries.some((entry) => entry.isIntersecting && entry.intersectionRect.width > 0 && entry.intersectionRect.height > 0);
    syncVisibility();
  }, { threshold: 0 });

  observer.observe(contactForm);
  if (typeof mobileViewport.addEventListener === 'function') mobileViewport.addEventListener('change', syncVisibility);
  else if (typeof mobileViewport.addListener === 'function') mobileViewport.addListener(syncVisibility);
})();
